// DYNAMIC CAD - DXF import tests.
// Fixtures in tests/fixtures/dxf were generated by generate_dxf_fixtures.py
// (ezdxf, MIT) in AutoCAD R12, 2000, 2010 and 2018 formats.
#include "dxf/DxfReader.h"
#include "entities/ArcEntity.h"
#include "entities/CircleEntity.h"
#include "entities/CurveEntities.h"
#include "entities/XLineEntity.h"
#include "entities/Annotation.h"
#include "entities/LineEntity.h"
